"use strict";const fs=require("fs");const path=require("path");const net=require("net");const{spawn,execFileSync}=require("child_process");const PROJECT_ROOT=path.resolve(__dirname,"../..");const BRIDGE_DIR=path.join(PROJECT_ROOT,".claude/gemini-bridge");const REVIEWS_DIR=path.join(BRIDGE_DIR,"reviews");const PENDING_FILE=path.join(BRIDGE_DIR,"pending-files.txt");const STATE_FILE=path.join(BRIDGE_DIR,"gemini-state.json");const LAST_REVIEW_FILE=path.join(BRIDGE_DIR,".last-review-at");const LOG_FILE=path.join(BRIDGE_DIR,"trigger.log");const SOCKET_PATH=path.join(BRIDGE_DIR,"gemini.sock");const BRIDGE_JS=path.join(__dirname,"gemini-bridge.js");const DEBOUNCE_MS=3e4;const IDLE_TIMEOUT_MS=6e5;const MIN_INTERVAL_MS=3e5;const DAILY_LIMIT=900;const MAX_FILES=20;const REVIEW_TIMEOUT_MS=15e4;function log(msg){try{ensureDirs();fs.appendFileSync(LOG_FILE,`[${(new Date).toISOString()}] ${msg}\n`,"utf8")}catch(_){}}function ensureDirs(){[BRIDGE_DIR,REVIEWS_DIR].forEach(d=>{if(!fs.existsSync(d))fs.mkdirSync(d,{recursive:true})})}function loadState(){try{if(!fs.existsSync(STATE_FILE))return initState();const raw=fs.readFileSync(STATE_FILE,"utf8");const s=JSON.parse(raw);const today=(new Date).toISOString().slice(0,10);if(s.date!==today){s.date=today;s.callCount=0}return s}catch(_){return initState()}}function initState(){return{date:(new Date).toISOString().slice(0,10),callCount:0,pendingReviews:[]}}function saveState(state){try{ensureDirs();fs.writeFileSync(STATE_FILE,JSON.stringify(state,null,2),"utf8")}catch(_){}}function readPendingFiles(){try{if(!fs.existsSync(PENDING_FILE))return[];const content=fs.readFileSync(PENDING_FILE,"utf8").trim();if(!content)return[];return[...new Set(content.split("\n").filter(Boolean))]}catch(_){return[]}}function writePendingFiles(files){try{ensureDirs();fs.writeFileSync(PENDING_FILE,files.join("\n")+"\n","utf8")}catch(_){}}function clearPendingFiles(){try{fs.writeFileSync(PENDING_FILE,"","utf8")}catch(_){}}function appendPending(filePath){try{ensureDirs();const existing=readPendingFiles();if(!existing.includes(filePath)){fs.appendFileSync(PENDING_FILE,filePath+"\n","utf8")}}catch(_){}}function readLastReviewAt(){try{if(!fs.existsSync(LAST_REVIEW_FILE))return 0;return parseInt(fs.readFileSync(LAST_REVIEW_FILE,"utf8").trim(),10)||0}catch(_){return 0}}function writeLastReviewAt(){try{fs.writeFileSync(LAST_REVIEW_FILE,String(Date.now()),"utf8")}catch(_){}}function trigger(filePath){if(!filePath)return;try{ensureDirs();const state=loadState();if(state.callCount>=DAILY_LIMIT)return;const lastAt=readLastReviewAt();if(Date.now()-lastAt<MIN_INTERVAL_MS){appendPending(filePath);return}const client=net.createConnection({path:SOCKET_PATH});client.on("connect",()=>{client.write(JSON.stringify({file:filePath})+"\n");client.end()});client.on("error",()=>{lazyStart(filePath)});client.setTimeout(2e3,()=>{client.destroy();lazyStart(filePath)})}catch(_){lazyStart(filePath)}}function lazyStart(filePath){try{if(fs.existsSync(SOCKET_PATH))fs.unlinkSync(SOCKET_PATH)}catch(_){}appendPending(filePath);const cleanEnv={...process.env};delete cleanEnv.CLAUDE_SANDBOX;delete cleanEnv.SANDBOX_MODE;try{const child=spawn("node",[__filename,"daemon"],{detached:true,stdio:"ignore",cwd:PROJECT_ROOT,env:cleanEnv});child.unref()}catch(e){log(`lazyStart failed: ${e.message}`)}}function runDaemon(){ensureDirs();let fileQueue=new Set;let debounceTimer=null;let idleTimer=null;let shuttingDown=false;let reviewInProgress=false;const pending=readPendingFiles();if(pending.length>0){pending.forEach(f=>fileQueue.add(f));clearPendingFiles();log(`Loaded ${pending.length} pending file(s) from previous session`)}const server=net.createServer(conn=>{if(shuttingDown){conn.destroy();return}resetIdleTimer();let buf="";conn.on("data",chunk=>{buf+=chunk.toString();const lines=buf.split("\n");buf=lines.pop();for(const line of lines){if(!line.trim())continue;try{const msg=JSON.parse(line);if(msg.file){fileQueue.add(msg.file);resetDebounceTimer();log(`Queued: ${msg.file} (queue: ${fileQueue.size})`)}if(msg.action==="status"){conn.write(JSON.stringify({queue:fileQueue.size,files:[...fileQueue],reviewInProgress:reviewInProgress,uptime:process.uptime()})+"\n")}}catch(_){}}});conn.on("error",()=>{})});try{if(fs.existsSync(SOCKET_PATH))fs.unlinkSync(SOCKET_PATH)}catch(_){}server.on("error",e=>{if(e.code==="EADDRINUSE"){log("Another daemon already running (EADDRINUSE). Exiting.");process.exit(0)}log(`Server error: ${e.message}`)});server.listen(SOCKET_PATH,()=>{log(`═══════════════════════════════════════════\n`+`[${(new Date).toISOString()}] Lazy daemon started\n`+`[${(new Date).toISOString()}] PID: ${process.pid}\n`+`[${(new Date).toISOString()}] Socket: ${SOCKET_PATH}\n`+`[${(new Date).toISOString()}] Debounce: ${DEBOUNCE_MS/1e3}s | Idle: ${IDLE_TIMEOUT_MS/6e4}min\n`+`[${(new Date).toISOString()}] ═══════════════════════════════════════════`);if(fileQueue.size>0){resetDebounceTimer()}});function resetDebounceTimer(){clearTimeout(debounceTimer);debounceTimer=setTimeout(()=>executeReview(),DEBOUNCE_MS)}function resetIdleTimer(){clearTimeout(idleTimer);idleTimer=setTimeout(()=>shutdown("idle"),IDLE_TIMEOUT_MS)}function executeReview(){if(fileQueue.size===0)return;if(reviewInProgress){debounceTimer=setTimeout(()=>executeReview(),1e4);return}const state=loadState();if(state.callCount>=DAILY_LIMIT){log(`Daily limit reached (${state.callCount}/${DAILY_LIMIT}). Clearing queue.`);fileQueue.clear();return}const files=[...fileQueue].slice(0,MAX_FILES);const remaining=[...fileQueue].slice(MAX_FILES);fileQueue=new Set(remaining);reviewInProgress=true;log(`Starting review for ${files.length} file(s): ${files.join(", ")}`);const child=spawn("node",[BRIDGE_JS,"review",...files],{cwd:PROJECT_ROOT,stdio:["ignore","pipe","pipe"],env:process.env});let stdout="";let stderr="";child.stdout.on("data",chunk=>{stdout+=chunk});child.stderr.on("data",chunk=>{stderr+=chunk});const timeout=setTimeout(()=>{log("Review timed out. Killing child.");child.kill("SIGKILL")},REVIEW_TIMEOUT_MS);child.on("close",code=>{clearTimeout(timeout);reviewInProgress=false;if(code===0){log("Review completed successfully.");if(stdout.trim())log(`Output: ${stdout.trim().slice(0,500)}`);state.callCount+=1;saveState(state);writeLastReviewAt();notifyIfCritical()}else{const errMsg=stderr.trim()||`Exit code ${code}`;log(`Review failed: ${errMsg.slice(0,300)}`)}if(fileQueue.size>0){resetDebounceTimer()}resetIdleTimer()});child.on("error",e=>{clearTimeout(timeout);reviewInProgress=false;log(`Review spawn error: ${e.message}`);resetIdleTimer()})}function notifyIfCritical(){try{const reviewFiles=fs.readdirSync(REVIEWS_DIR).filter(f=>f.endsWith(".json")).sort().reverse();if(reviewFiles.length===0)return;const latest=JSON.parse(fs.readFileSync(path.join(REVIEWS_DIR,reviewFiles[0]),"utf8"));if(latest.status==="completed"&&latest.needsAttention){const criticalCount=(latest.issues||[]).filter(i=>i.severity==="critical").length;const msg=criticalCount>0?`Gemini: ${criticalCount}건의 critical 이슈 발견!`:`Gemini: 코드 리뷰 주의 필요`;try{const safeMsg=msg.replace(/["\\]/g,"");execFileSync("osascript",["-e",`display notification "${safeMsg}" with title "Claude Code - KiiPS" sound name "Basso"`],{timeout:5e3,stdio:"ignore"})}catch(_){}log(`Notification: ${msg}`)}}catch(_){}}function shutdown(reason){if(shuttingDown)return;shuttingDown=true;clearTimeout(debounceTimer);clearTimeout(idleTimer);log(`Shutting down (${reason}). Queue: ${fileQueue.size} file(s).`);if(fileQueue.size>0){writePendingFiles([...fileQueue]);log(`Backed up ${fileQueue.size} file(s) to pending-files.txt`)}server.close(()=>{try{fs.unlinkSync(SOCKET_PATH)}catch(_){}log("Daemon stopped.");process.exit(0)});setTimeout(()=>{try{fs.unlinkSync(SOCKET_PATH)}catch(_){}process.exit(0)},3e3)}process.on("SIGTERM",()=>shutdown("SIGTERM"));process.on("SIGINT",()=>shutdown("SIGINT"));process.on("uncaughtException",e=>{log(`Uncaught exception: ${e.message}`);if(fileQueue.size>0)writePendingFiles([...fileQueue]);try{fs.unlinkSync(SOCKET_PATH)}catch(_){}process.exit(1)});resetIdleTimer()}function showStatus(){const state=loadState();console.log("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");console.log("GEMINI AUTO-TRIGGER STATUS (lazy daemon)");console.log("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n");console.log(`Date       : ${state.date}`);console.log(`Call count : ${state.callCount} / ${DAILY_LIMIT}`);console.log(`Socket     : ${SOCKET_PATH}`);const socketExists=fs.existsSync(SOCKET_PATH);console.log(`Daemon     : ${socketExists?"active":"idle"}`);if(socketExists){const client=net.createConnection({path:SOCKET_PATH});client.on("connect",()=>{client.write(JSON.stringify({action:"status"})+"\n")});client.on("data",data=>{try{const status=JSON.parse(data.toString().trim());console.log(`Queue      : ${status.queue} file(s)`);console.log(`Reviewing  : ${status.reviewInProgress?"yes":"no"}`);console.log(`Uptime     : ${Math.round(status.uptime)}s`)}catch(_){}client.end()});client.on("error",()=>{console.log("(daemon not responding)")});client.setTimeout(3e3,()=>{client.destroy()})}const lastAt=readLastReviewAt();if(lastAt>0){const ago=Math.round((Date.now()-lastAt)/1e3);console.log(`Last review: ${ago}s ago`)}const pending=readPendingFiles();if(pending.length>0){console.log(`Pending    : ${pending.length} file(s)`)}console.log("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n")}const mode=process.argv[2];if(mode==="daemon"){runDaemon()}else if(mode==="status"){showStatus()}else{module.exports={trigger:trigger}}